/* @lc app=leetcode id=3863 lang=kotlin */ class Solution { fun minOperations(s: String): Int = s.toList().sorted().joinToString("").let { st -> if (s == st) 0 else s.length.let { n -> (if (s.indices.first { s[it] != st[it] } == 0 && s.indices.last { s[it] != st[it] } == n - 1) (if (n == 2) -1 else if (s.indexOf(st[0]) <= n - 2 || s.lastIndexOf(st[n - 1]) >= 1) 2 else 3) else 1) } } }